import { useEffect, useRef } from 'react';
import { useSelector } from 'react-redux';
import { selectActiveChat, selectLoading } from '../../store/slices/chatSlice';
import MessageBubble from './MessageBubble';
import ThinkingDots from '../ui/ThinkingDots';
import { BotAvatar } from '../ui/Avatar';
import { useTheme } from '../../hooks/useTheme';

export default function MessageList({ startMode = false }) {
  const activeChat = useSelector(selectActiveChat);
  const loading    = useSelector(selectLoading);
  const { textHex, mutedHex, msgBotHex } = useTheme();
  const bottomRef  = useRef(null);

  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [activeChat?.messages, loading]);

  const isEmpty = !activeChat || activeChat.messages.length === 0;

  if (startMode) {
    return (
      <div style={{ flex: 1, overflowY: 'auto', padding: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 12, opacity: 0.72, transform: 'translateY(-96px)' }}>
          <div style={{ width: 64, height: 64, borderRadius: 20, background: 'linear-gradient(135deg,#6366f1,#8b5cf6)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <svg width="32" height="32" viewBox="0 0 28 28" fill="none"><circle cx="14" cy="14" r="12" stroke="white" strokeWidth="2"/><circle cx="10" cy="12.5" r="2" fill="white"/><circle cx="18" cy="12.5" r="2" fill="white"/><path d="M10 18c1.2 1.5 6.8 1.5 8 0" stroke="white" strokeWidth="1.5" strokeLinecap="round"/></svg>
          </div>
          <p style={{ fontSize: 22, fontWeight: 700, color: textHex, fontFamily: "'Space Grotesk'" }}>How can I help you?</p>
          <p style={{ fontSize: 14, color: mutedHex }}>Start a conversation below</p>
        </div>
      </div>
    );
  }

  return (
    <div style={{ flex: 1, overflowY: 'auto', padding: '20px 0' }}>
      {isEmpty && (
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100%', gap: 12, opacity: 0.6 }}>
          <div style={{ width: 64, height: 64, borderRadius: 20, background: 'linear-gradient(135deg,#6366f1,#8b5cf6)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <svg width="32" height="32" viewBox="0 0 28 28" fill="none"><circle cx="14" cy="14" r="12" stroke="white" strokeWidth="2"/><circle cx="10" cy="12.5" r="2" fill="white"/><circle cx="18" cy="12.5" r="2" fill="white"/><path d="M10 18c1.2 1.5 6.8 1.5 8 0" stroke="white" strokeWidth="1.5" strokeLinecap="round"/></svg>
          </div>
          <p style={{ fontSize: 18, fontWeight: 600, color: textHex, fontFamily: "'Space Grotesk'" }}>How can I help you?</p>
          <p style={{ fontSize: 14, color: mutedHex }}>Start a conversation below</p>
        </div>
      )}

      <div style={{ maxWidth: 820, margin: '0 auto', width: '100%' }}>
        {activeChat?.messages.map((msg) => (
          <MessageBubble key={msg.id} message={msg}/>
        ))}
        {loading && (
          <div style={{ display: 'flex', gap: 12, padding: '8px 20px', animation: 'fadeUp 0.2s ease' }}>
            <BotAvatar/>
            <div style={{ padding: '10px 14px', borderRadius: '16px 16px 16px 4px', background: msgBotHex }}>
              <ThinkingDots/>
            </div>
          </div>
        )}
      </div>
      <div ref={bottomRef}/>
    </div>
  );
}
